  if (!value || !Array.isArray(value.sources) || !Array.isArray(value.claims)) throw new Error('INVALID_EVIDENCE');
  const ids = new Set();
  for (const source of value.sources) {
    requireText(source.id,'SOURCE_ID'); requireText(source.title,'SOURCE_TITLE');
    if (ids.has(source.id)) throw new Error('DUPLICATE_SOURCE_ID');
