    if (!item || (!text(item.contact_id) && !/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(item.domain??'') && (!Array.isArray(item.aliases)||!item.aliases.some(a=>validEmail(email(a)))))) throw new Error('UNMATCHABLE_EXCLUSION_RECORD');
